// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _test(address owner) internal {
        vm.assume(owner != address(0));
        try c.Command(owner, "") {} catch { return; }
        bool reverted = true;
        try c.withdraw() { reverted = false; } catch {}
        assertTrue(!reverted);
    }

    function testFuzz_test(address owner) public {
        _test(owner);
    }

    receive() external payable {}
}
